def find_gaps_and_fill(grid, marker, interior_width=24, interior_height=24):
    # Pattern: fill gaps between adjacent marker-blocks both horizontally and vertically

    # Track which positions get filled with 2
    filled = set()

    # Horizontal gaps: for each row, find gap-cells between marker-blocks
    for r in range(grid.shape[0]):
