            start = cols_with_marker[i] + 1
            end = cols_with_marker[i+1] - 1
            if end >= start:
                for c in range(start, end+1):
                    if grid[r][c] != marker:
                        filled.add((r, c))

    # Vertical gaps: for each col, find gap-cells between marker-blocks
    for c in range(grid.shape[1]):
        rows_with_marker = sorted(r for r in range(grid.shape[0]) if grid[r][c] == marker)
